using System.Numerics;
using System.Text;
namespace Zuzel;
static class Verification
{
    public static int Run(){var report=new StringBuilder();try{void Check(bool condition,string name){if(!condition)throw new Exception(name);report.AppendLine("PASS "+name);}
        var race=new Race();var inputs=new Drive[4];for(int n=0;n<1200;n++)race.Step(1f/120,inputs);Check(race.Riders.All(r=>r.Speed<.01f&&Math.Abs(r.Distance+Race.GridDistance)<.1f),"No throttle: all four motorcycles remain stationary");
        race.Reset();inputs[0]=new(1,0);for(int n=0;n<1200;n++)race.Step(1f/120,inputs);Check(race.Riders[0].WallHits>0&&race.Riders[0].Distance<Race.Length*.5f,"Throttle without steering: hits wall and cannot complete a lap");Check(race.Riders.Skip(1).All(r=>r.Speed<.01f),"Independent input: one player cannot accelerate the other three");
        foreach(float p in new[]{0f,Race.A,Race.A+MathF.PI*Race.R,3*Race.A+MathF.PI*Race.R,3*Race.A+2*MathF.PI*Race.R,Race.Length-.01f}){var position=Race.TrackPoint(p).Point;float difference=Math.Abs(Race.Phase(position)-p);Check(difference<.05f||Math.Abs(difference-Race.Length)<.05f,$"Track phase continuity at {p:0.0}");}
        race.Reset();inputs=new Drive[4];inputs[0]=new(0,1);for(int n=0;n<120;n++)race.Step(1f/120,inputs);Check(Math.Abs(Race.Wrap(race.Riders[0].Heading-MathF.PI))>.7f&&race.Riders[0].Speed<.01f,"Steering works at standstill without moving automatically");
        race.Reset();var stuck=race.Riders[0];stuck.Pos=new(640,Race.Cy-Race.Outer);stuck.Heading=-MathF.PI/2;stuck.PreviousPhase=Race.Phase(stuck.Pos);inputs=new Drive[4];inputs[0]=new(1,1);float recoveredSpeed=0,recoveredTravel=0;for(int n=0;n<480;n++){race.Step(1f/120,inputs);recoveredSpeed=Math.Max(recoveredSpeed,stuck.Speed);recoveredTravel=Math.Max(recoveredTravel,Vector2.Distance(stuck.Pos,new Vector2(640,Race.Cy-Race.Outer)));}report.AppendLine($"Wall recovery: speed={stuck.Speed}, position={stuck.Pos}, heading={stuck.Heading}, hits={stuck.WallHits}");Check(recoveredSpeed>60&&recoveredTravel>120,"A stationary motorcycle can steer and accelerate away from the wall");
        race.Reset();for(int n=0;n<120*180&&race.Results.Count<4;n++){for(int i=0;i<4;i++)inputs[i]=race.AI(race.Riders[i]);race.Step(1f/120,inputs);}foreach(var r in race.Riders)report.AppendLine($"Rider {r.Id+1}: distance={r.Distance:0}, finish={r.FinishTime:0.00}, walls={r.WallHits}");Check(race.Results.Count==4,"Four independent riders finish four laps");Check(race.Results.Distinct().Count()==4,"Unique race classification");Check(race.Riders.All(r=>float.IsFinite(r.Pos.X)&&float.IsFinite(r.Vel.X)),"Finite physics positions and velocities");
        var clockwise=new Race();var back=clockwise.Riders[0];back.PreviousPhase=Race.Phase(Race.TrackPoint(100).Point);back.Pos=Race.TrackPoint(100).Point;back.Distance=100;back.Heading=0;inputs=new Drive[4];inputs[0]=new(1,0);for(int n=0;n<60;n++)clockwise.Step(1f/120,inputs);Check(back.Distance<100,"Driving backwards does not count forward progress");
        race.Reset();Check(race.Time==0&&race.Results.Count==0&&race.Riders.All(r=>!r.Finished),"Restart clears race state");
        inputs=new Drive[4];for(int n=0;n<420;n++)race.Stage(1f/120,inputs);Check(race.Riders.All(r=>!r.Disqualified)&&race.Time==0,"Waiting at the tape causes no false start and no race-time advance");
        race.Reset();inputs[0]=new(1,0);for(int n=0;n<240;n++)race.Stage(1f/120,inputs);Check(race.Riders[0].Disqualified&&race.Riders[0].Finished,"Riding into the tape before the start disqualifies that rider");Check(race.Riders.Skip(1).All(r=>!r.Disqualified),"One false start does not exclude other players");
        for(int n=0;n<120*180&&race.Results.Count<4;n++){for(int i=0;i<4;i++)inputs[i]=race.AI(race.Riders[i]);race.Step(1f/120,inputs);}Check(race.Results.Count==4&&race.Results[^1]==0,"A disqualified rider is ranked last after remaining riders finish");
        race.Reset();inputs=Enumerable.Repeat(new Drive(1,0),4).ToArray();for(int n=0;n<240;n++)race.Stage(1f/120,inputs);Check(race.Results.Count==4&&race.Riders.All(r=>r.Disqualified),"Four tape exclusions end the race without hanging");
        using(var keyboard=new GameKeyboard(()=>new IntPtr(123),()=>true)){int transitions=0;keyboard.Pressed+=_=>transitions++;int[] keys={87,65,68,38,37,39,73,74,76,104,100,102};foreach(int key in keys){var msg=Message.Create(new IntPtr(123),0x100,new IntPtr(key),IntPtr.Zero);keyboard.PreFilterMessage(ref msg);}Check(keys.All(keyboard.IsDown),"All twelve driving keys can be held independently");var watch=System.Diagnostics.Stopwatch.StartNew();for(int n=0;n<1000000;n++){var msg=Message.Create(new IntPtr(123),0x100,new IntPtr(keys[n%keys.Length]),new IntPtr(1L<<30));keyboard.PreFilterMessage(ref msg);}watch.Stop();report.AppendLine($"1,000,000 repeated key messages: {watch.Elapsed.TotalMilliseconds:F2} ms");Check(transitions==12,"Held-key repeats do not retrigger interface actions");Check(watch.Elapsed.TotalSeconds<2,"Held-key handler remains bounded under a million repeated messages");foreach(int key in keys){var msg=Message.Create(new IntPtr(123),0x101,new IntPtr(key),IntPtr.Zero);keyboard.PreFilterMessage(ref msg);}Check(keys.All(key=>!keyboard.IsDown(key)),"Releasing keys clears all driving controls");}
        var posed=new Rider{Pos=new(Race.Cx,Race.Cy-Race.R),Vel=new(-150,0)};for(int i=0;i<60;i++)Race.UpdatePose(posed,1f/120);Check(posed.LegExtension==0,"Straight: left foot remains on the footpeg");posed.Pos=Race.TrackPoint(Race.A+MathF.PI*Race.R/2).Point;for(int i=0;i<60;i++)Race.UpdatePose(posed,1f/120);Check(posed.LegExtension>.99f,"Corner at speed: left leg extends");posed.Pos=Race.TrackPoint(2*Race.A+MathF.PI*Race.R).Point;for(int i=0;i<30;i++)Race.UpdatePose(posed,1f/120);Check(posed.LegExtension<.01f,"Leaving the corner retracts the leg on the straight");posed.Pos=Race.TrackPoint(Race.A+MathF.PI*Race.R/2).Point;posed.Vel=Vector2.Zero;for(int i=0;i<60;i++)Race.UpdatePose(posed,1f/120);Check(posed.LegExtension==0,"Standing still on a corner does not extend the leg");
        using(var sprites=new RiderSprites()){Check(sprites.HasStraightPose,"The straight-riding pose is embedded in the executable");Check(sprites.RigidPartsStayIdentical(),"Helmet and both wheels remain pixel-identical in every leg pose");}
        var interpolated=RiderSprites.Presentation(new Rider{PreviousPosition=Vector2.Zero,Pos=new(10,20),PreviousHeading=179*MathF.PI/180,Heading=-179*MathF.PI/180},.5f);Check(Vector2.Distance(interpolated.Position,new(5,10))<.001f&&Math.Abs(Math.Abs(interpolated.Heading)-MathF.PI)<.001f,"Position interpolation and rotation take the short path across the angle boundary");
        Race FinishFixture(int rotation,bool excludeLast=false){var fixture=new Race();for(int i=0;i<4;i++){int id=(i+rotation)%4;fixture.Results.Add(id);fixture.Riders[id].Finished=true;fixture.Riders[id].FinishTime=50+i;fixture.Riders[id].Disqualified=excludeLast&&i==3;}return fixture;}
        var competition=new Tournament();competition.Start(CompetitionMode.Individual);Check(!competition.Advance(),"Cannot skip an unfinished heat");var expected=new int[4];for(int heat=1;heat<=15;heat++){var fixture=FinishFixture((heat-1)%4);Check(competition.Record(fixture),$"Heat {heat} counted");for(int place=0;place<4;place++)expected[fixture.Results[place]]+=3-place;int sum=competition.Points.Sum();Check(!competition.Record(fixture)&&competition.Points.Sum()==sum,"Reopening results cannot count a heat twice");Check(competition.Points.SequenceEqual(expected),"Points accumulate across all completed heats");if(heat<15)Check(competition.Advance()&&competition.CurrentHeat==heat+1,"Next heat preserves the points");}Check(competition.Complete&&competition.History.Count==15&&!competition.Advance(),"Competition ends at exactly fifteen heats");Check(competition.Points.Sum()==90,"Fifteen normal heats award ninety points in total");
        competition.Start(CompetitionMode.Team);Check(competition.History.Count==0&&competition.Points.Sum()==0,"New competition resets all totals");competition.Record(FinishFixture(0,true));Check(competition.TeamPoints(0)==4&&competition.TeamPoints(1)==2,"Team score sums red/white versus blue/yellow");Check(competition.HeatPoints(3)==0,"Tape exclusion awards zero tournament points");for(int heat=2;heat<=15;heat++){competition.Advance();competition.Record(FinishFixture(0));}Check(competition.TeamPoints(0)==60&&competition.TeamPoints(1)==30&&competition.ResultText().Contains("A"),"Final team result totals all fifteen heats");
        var excludedFixture=FinishFixture(0);excludedFixture.Riders[2].Disqualified=true;excludedFixture.Riders[3].Disqualified=true;var exclusions=new Tournament();exclusions.Start(CompetitionMode.Individual);exclusions.Record(excludedFixture);Check(exclusions.Points[2]==0&&exclusions.Points[3]==0&&exclusions.Points.Sum()==5,"Multiple exclusions all award zero points");
        var tied=new Tournament();tied.Start(CompetitionMode.Team);for(int heat=1;heat<=15;heat++){var fixture=FinishFixture(0);fixture.Results.Clear();fixture.Results.AddRange(new[]{0,1,3,2});tied.Record(fixture);if(heat<15)tied.Advance();}Check(tied.TeamPoints(0)==45&&tied.TeamPoints(1)==45&&tied.ResultText().Contains("Remis"),"A fifteen-heat team draw stays a draw without adding a sixteenth heat");
        var full=new Tournament();full.Start(CompetitionMode.Team);var fullRace=new Race();for(int heat=1;heat<=15;heat++){fullRace.Reset(heat-1);var positions=fullRace.Riders.Select(r=>r.Pos.Y).ToArray();Check(positions.Distinct().Count()==4,"Each heat has four different starting gates");for(int n=0;n<120*180&&fullRace.Results.Count<4;n++){for(int i=0;i<4;i++)inputs[i]=fullRace.AI(fullRace.Riders[i]);fullRace.Step(1f/120,inputs);}Check(fullRace.Results.Count==4&&full.Record(fullRace),$"Full simulated heat {heat} finishes and adds points");if(heat<15)full.Advance();}Check(full.Complete&&full.Points.Sum()==90,"A complete simulated fifteen-heat match finishes with correct totals");
        report.AppendLine("ALL TESTS PASSED");File.WriteAllText("verification.txt",report.ToString());return 0;
    }catch(Exception e){report.AppendLine("FAIL "+e);File.WriteAllText("verification.txt",report.ToString());return 1;}}
}
